//! Rate limit of external ICMPv4 errors that NAT44 translates toward an
//! inside host (RFC 5508 REQ-10 f, by analogy with RFC 1812 §4.3.2.8;
//! requirements NAT44-065).
//!
//! RFC 1812 §4.3.2.8 lets a router limit the errors it sends "to a given
//! source host ... at most once per T milliseconds" and leaves the
//! granularity to the implementor. A translated error is not generated by
//! the router, but it is delivered by it, so the limit applies per delivery
//! path: the inside host the error goes to and the quoted remote address of
//! the flow it reports on. A sweep or flood naming remote R spends only the
//! budget of the inside host's flows to R, so its Path MTU Discovery and
//! traceroute toward every other remote keep their own budget, and no other
//! inside host is touched.
//!
//! The state is a fixed array of [`ICMPV4_TRANSLATED_LIMIT_BUCKETS`]
//! buckets, one `u64` each (32 KiB), inside the generated-error runtime: no
//! allocation, no table scan, and one keyed hash plus one bucket read and
//! write per translated error. The bucket is a SipHash of (inside address,
//! quoted remote address) under a secret per-publication key, in its own
//! domain, so which pairs share a bucket is unpredictable and changes with
//! every key. Two pairs share one with probability 1/4096; nobody without
//! the key can pick a pair that shares a bucket with a victim's, and a
//! sender can only spend buckets of pairs with a live flow (an error about
//! any other pair is refused before the limiter). A new key (every applied
//! publication) empties every bucket, since old arrival times would
//! otherwise land on unrelated pairs.
//!
//! Each bucket runs the generic cell rate algorithm (GCRA, the virtual
//! scheduling form of a token bucket) on a time axis scaled by the rate, so
//! every quantity is an exact integer: one error costs 1000 scaled units and
//! the clock advances `rate` units per millisecond. `burst` errors pass at
//! one instant, and after that one more each `1000 / rate` ms. Arithmetic
//! that would overflow refuses the error (fail closed).

use crate::fixed_directory::{DirectoryHashDomain, DirectoryHashKey};
use crate::{Ipv4Address, MonotonicMillis};

/// Buckets of the translated ICMPv4 error limiter (32 KiB of state).
pub const ICMPV4_TRANSLATED_LIMIT_BUCKETS: usize = 4096;

/// Default sustained translated errors per second per (inside host, quoted
/// remote address).
///
/// A traceroute from one inside host receives at most a few Time Exceeded
/// errors per hop (3 probes per hop and 16 probes in flight for the classic
/// Linux traceroute, about 1 per hop per second for mtr), and Path MTU
/// Discovery receives one Fragmentation Needed per flow and path change, so
/// 100 per second with a burst of 100 never limits them while bounding what
/// a sweep or a flood can deliver on one path.
pub const ICMPV4_DEFAULT_TRANSLATED_RATE_PER_SECOND: u32 = 100;

/// Default number of translated errors one (inside host, quoted remote
/// address) can receive at one instant (see
/// [`ICMPV4_DEFAULT_TRANSLATED_RATE_PER_SECOND`]).
pub const ICMPV4_DEFAULT_TRANSLATED_BURST: u32 = 100;

/// Largest accepted translated rate (per second) and burst. Both at this
/// value is the effectively-off setting: a million errors at once and a
/// million per second per path.
pub const ICMPV4_MAX_TRANSLATED_LIMIT: u32 = 1_000_000;

/// Scaled cost of one error: the clock advances `rate` scaled units per
/// millisecond, so `rate` errors per 1000 ms cost 1000 units each.
const COST: u64 = 1_000;

/// Public fixed key of runtimes built without a publication key (tests and
/// benches). Production activation and every publication supply a secret.
const FIXED_KEY: DirectoryHashKey =
    match DirectoryHashKey::new(0x7472_616e_736c_6174, 0x6564_2d69_636d_7034) {
        Ok(key) => key,
        Err(_) => panic!("nonzero fixed key"),
    };

/// Fixed-size keyed GCRA limiter for translated ICMPv4 errors.
#[derive(Clone, Eq, PartialEq)]
pub(crate) struct TranslatedIcmpv4Limiter {
    key: DirectoryHashKey,
    /// Theoretical arrival time of the next conforming error, in scaled
    /// units (`now_ms * rate`). Zero is the empty bucket (a full burst).
    arrival: [u64; ICMPV4_TRANSLATED_LIMIT_BUCKETS],
}

impl std::fmt::Debug for TranslatedIcmpv4Limiter {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("TranslatedIcmpv4Limiter([REDACTED])")
    }
}

impl TranslatedIcmpv4Limiter {
    pub(crate) const EMPTY: Self = Self::with_key(FIXED_KEY);

    pub(crate) const fn with_key(key: DirectoryHashKey) -> Self {
        Self {
            key,
            arrival: [0; ICMPV4_TRANSLATED_LIMIT_BUCKETS],
        }
    }

    /// Installs `key`. A different key empties every bucket: the old
    /// arrival times would otherwise belong to unrelated pairs.
    pub(crate) fn rekey(&mut self, key: DirectoryHashKey) {
        if key != self.key {
            self.key = key;
            self.arrival = [0; ICMPV4_TRANSLATED_LIMIT_BUCKETS];
        }
    }

    pub(crate) fn key_matches(&self, key: DirectoryHashKey) -> bool {
        self.key == key
    }

    /// Bucket of the delivery path `host` (inside) and `remote` (the quoted
    /// remote address): a keyed SipHash in its own domain.
    pub(crate) fn bucket(&self, host: Ipv4Address, remote: Ipv4Address) -> usize {
        let word = u64::from(u32::from_be_bytes(host.octets())) << 32
            | u64::from(u32::from_be_bytes(remote.octets()));
        let hash = self
            .key
            .hash_words(DirectoryHashDomain::Icmpv4TranslatedLimit, &[word]);
        (hash as usize) & (ICMPV4_TRANSLATED_LIMIT_BUCKETS - 1)
    }

    /// Admits one translated error toward `host` about a flow with
    /// `remote`, at `now`, or refuses it without changing any state.
    ///
    /// `rate` is per second and `burst` the number admitted at one instant;
    /// both are at least 1 (the policy constructor refuses 0). A clock that
    /// moves backward only makes the bucket look fuller, and a clock so
    /// large that the scaled time overflows refuses every error, so the
    /// limiter fails closed and never admits more than the limit. O(1): one
    /// hash and one bucket, no scan.
    pub(crate) fn admit(
        &mut self,
        host: Ipv4Address,
        remote: Ipv4Address,
        now: MonotonicMillis,
        rate: u32,
        burst: u32,
    ) -> bool {
        let bucket = self.bucket(host, remote);
        let slot = &mut self.arrival[bucket];
        let Some(now) = now.0.checked_mul(u64::from(rate)) else {
            return false;
        };
        let tolerance = u64::from(burst.saturating_sub(1)) * COST;
        let arrival = (*slot).max(now);
        if arrival - now > tolerance {
            return false;
        }
        let Some(next) = arrival.checked_add(COST) else {
            return false;
        };
        *slot = next;
        true
    }

    /// Every bucket is empty (the key is not part of the comparison: the
    /// constructor state of a keyed runtime is pristine too).
    pub(crate) fn is_pristine(&self) -> bool {
        self.arrival.iter().all(|arrival| *arrival == 0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const HOST: Ipv4Address = Ipv4Address::from_octets([10, 0, 0, 10]);
    const REMOTE: Ipv4Address = Ipv4Address::from_octets([198, 51, 100, 20]);

    fn key(index: u64) -> DirectoryHashKey {
        DirectoryHashKey::new(
            0x9e37_79b9_7f4a_7c15_u64.wrapping_mul(index + 1),
            0xc2b2_ae3d_27d4_eb4f_u64.wrapping_mul(index + 7),
        )
        .unwrap()
    }

    fn admitted_on(
        limiter: &mut TranslatedIcmpv4Limiter,
        host: Ipv4Address,
        remote: Ipv4Address,
        now: u64,
        rate: u32,
        burst: u32,
        attempts: u32,
    ) -> u32 {
        (0..attempts)
            .map(|_| u32::from(limiter.admit(host, remote, MonotonicMillis(now), rate, burst)))
            .sum()
    }

    fn admitted(
        limiter: &mut TranslatedIcmpv4Limiter,
        host: Ipv4Address,
        now: u64,
        rate: u32,
        burst: u32,
        attempts: u32,
    ) -> u32 {
        admitted_on(limiter, host, REMOTE, now, rate, burst, attempts)
    }

    #[test]
    fn burst_passes_at_one_instant_and_then_one_per_interval() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        assert_eq!(admitted(&mut limiter, HOST, 5_000, 100, 100, 1_000), 100);
        // 100 per second: one error each 10 ms, never early.
        assert_eq!(admitted(&mut limiter, HOST, 5_009, 100, 100, 10), 0);
        assert_eq!(admitted(&mut limiter, HOST, 5_010, 100, 100, 10), 1);
        assert_eq!(admitted(&mut limiter, HOST, 5_019, 100, 100, 10), 0);
        assert_eq!(admitted(&mut limiter, HOST, 5_020, 100, 100, 10), 1);
        // Idle for a full second refills the whole burst and no more.
        assert_eq!(admitted(&mut limiter, HOST, 7_000, 100, 100, 1_000), 100);
    }

    #[test]
    fn sustained_rate_is_exact_over_ten_seconds() {
        for (rate, burst) in [(1, 1), (3, 1), (100, 1), (100, 100), (1_500, 2), (5_000, 5)] {
            let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
            let mut total = 0_u64;
            // Offer far more than the rate every millisecond for 10 s.
            for now in 1_000..11_000 {
                total += u64::from(admitted(&mut limiter, HOST, now, rate, burst, 20));
            }
            // The burst at the first reading, then `rate` per second over
            // the 9999 ms that follow.
            let expected = u64::from(burst) + u64::from(rate) * 9_999 / 1_000;
            assert!(
                total.abs_diff(expected) <= 1,
                "rate {rate} burst {burst}: {total} vs {expected}"
            );
        }
    }

    /// Errors offered at one clock reading pass at most `burst` at a time,
    /// so a rate above `burst` per millisecond is capped at `burst` per
    /// clock reading (documented on the policy).
    #[test]
    fn one_clock_reading_admits_at_most_the_burst() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        let max = ICMPV4_MAX_TRANSLATED_LIMIT;
        assert_eq!(admitted(&mut limiter, HOST, 1_000, max, 1, 100), 1);
        assert_eq!(admitted(&mut limiter, HOST, 1_001, max, 1, 100), 1);
        assert_eq!(admitted(&mut limiter, HOST, 1_002, max, 7, 100), 7);
        // The effectively-off setting: a million at once.
        assert_eq!(
            admitted(&mut limiter, HOST, 1_003, max, max, 200_000),
            200_000
        );
    }

    #[test]
    fn burst_one_admits_exactly_one_then_waits_the_full_interval() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        assert_eq!(admitted(&mut limiter, HOST, 1_000, 1, 1, 5), 1);
        assert_eq!(admitted(&mut limiter, HOST, 1_999, 1, 1, 5), 0);
        assert_eq!(admitted(&mut limiter, HOST, 2_000, 1, 1, 5), 1);
    }

    /// Review M1: under the old unkeyed XOR fold, 10.0.1.5 and 10.0.2.6
    /// (and every other pair whose octets XOR alike) always shared a
    /// bucket. Under the keyed hash such pairs share one with probability
    /// 1/4096 per key: over 64 keys and 16 colliding pairs (1024 trials,
    /// about 0.25 expected) at most 3 share.
    #[test]
    fn pairs_the_xor_fold_collided_get_separate_buckets_under_the_key() {
        let mut shared = 0;
        for index in 0..64 {
            let limiter = TranslatedIcmpv4Limiter::with_key(key(index));
            for step in 0..16_u8 {
                let a = Ipv4Address::from_octets([10, 0, 1, 5 + step]);
                let b = Ipv4Address::from_octets([10, 0, 2, (5 + step) ^ 3]);
                assert_eq!(
                    a.octets().iter().fold(0, |x, y| x ^ y),
                    b.octets().iter().fold(0, |x, y| x ^ y),
                    "the pair collided under the XOR fold"
                );
                shared += usize::from(limiter.bucket(a, REMOTE) == limiter.bucket(b, REMOTE));
            }
        }
        assert!(shared <= 3, "{shared} of 1024");
    }

    /// Rotating the key moves (almost) every pair to another bucket and
    /// empties the limiter; installing the same key changes nothing.
    #[test]
    fn a_new_key_remaps_every_pair_and_empties_the_buckets() {
        let mut limiter = TranslatedIcmpv4Limiter::with_key(key(1));
        let before: Vec<usize> = (0..=255_u8)
            .map(|last| limiter.bucket(Ipv4Address::from_octets([192, 168, 7, last]), REMOTE))
            .collect();
        assert_eq!(admitted(&mut limiter, HOST, 1_000, 1, 1, 5), 1);
        limiter.rekey(key(1));
        assert_eq!(admitted(&mut limiter, HOST, 1_000, 1, 1, 5), 0, "same key");
        limiter.rekey(key(2));
        assert!(limiter.is_pristine());
        let moved = (0..=255_u8)
            .filter(|last| {
                limiter.bucket(Ipv4Address::from_octets([192, 168, 7, *last]), REMOTE)
                    != before[usize::from(*last)]
            })
            .count();
        assert!(moved >= 250, "{moved} of 256 moved");
        assert_eq!(admitted(&mut limiter, HOST, 1_000, 1, 1, 5), 1);
    }

    /// Review L1: the budget is per (inside host, quoted remote). An
    /// exhausted path leaves the host's other paths and other hosts alone.
    #[test]
    fn budgets_are_per_inside_host_and_quoted_remote() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        let other_host = Ipv4Address::from_octets([10, 0, 0, 11]);
        let other_remote = Ipv4Address::from_octets([192, 0, 2, 30]);
        let paths = [(HOST, REMOTE), (HOST, other_remote), (other_host, REMOTE)];
        for (index, (host, remote)) in paths.iter().enumerate() {
            for (other, (other_host, other_remote)) in paths.iter().enumerate() {
                if index != other {
                    assert_ne!(
                        limiter.bucket(*host, *remote),
                        limiter.bucket(*other_host, *other_remote)
                    );
                }
            }
        }
        for (host, remote) in paths {
            assert_eq!(admitted_on(&mut limiter, host, remote, 1_000, 10, 5, 50), 5);
        }
    }

    #[test]
    fn refused_errors_do_not_change_state_and_regression_fails_closed() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        assert_eq!(admitted(&mut limiter, HOST, 10_000, 10, 2, 2), 2);
        let full = limiter.clone();
        assert_eq!(admitted(&mut limiter, HOST, 10_000, 10, 2, 100), 0);
        assert_eq!(limiter, full);
        // A clock read before the last admission sees a fuller bucket.
        assert_eq!(admitted(&mut limiter, HOST, 9_000, 10, 2, 100), 0);
        assert_eq!(limiter, full);
        assert_eq!(admitted(&mut limiter, HOST, 10_100, 10, 2, 100), 1);
    }

    /// Adversarial cost: whatever the addresses, clock, or how full the
    /// limiter is, one admission reads and writes exactly one fixed bucket
    /// of a fixed-size array (no scan, no allocation), so a flood costs the
    /// same per error as one error.
    #[test]
    fn every_admission_touches_at_most_one_bucket() {
        let mut limiter = TranslatedIcmpv4Limiter::with_key(key(3));
        let mut seed = 0x9e37_79b9_u32;
        for step in 0..5_000_u64 {
            seed ^= seed << 13;
            seed ^= seed >> 17;
            seed ^= seed << 5;
            let host = Ipv4Address::from_octets(seed.to_be_bytes());
            let remote = Ipv4Address::from_octets(seed.rotate_left(11).to_be_bytes());
            let before = limiter.clone();
            limiter.admit(host, remote, MonotonicMillis(step / 7), 3, 2);
            let changed: Vec<usize> = (0..ICMPV4_TRANSLATED_LIMIT_BUCKETS)
                .filter(|index| before.arrival[*index] != limiter.arrival[*index])
                .collect();
            assert!(changed.len() <= 1);
            assert!(changed
                .iter()
                .all(|index| *index == limiter.bucket(host, remote)));
        }
        assert_eq!(
            core::mem::size_of::<TranslatedIcmpv4Limiter>(),
            8 * ICMPV4_TRANSLATED_LIMIT_BUCKETS + core::mem::size_of::<DirectoryHashKey>()
        );
    }

    /// Review N1: a clock so large that the scaled time overflows refuses
    /// every error instead of saturating into an unlimited bucket.
    #[test]
    fn an_overflowing_clock_fails_closed() {
        let mut limiter = TranslatedIcmpv4Limiter::EMPTY;
        let max = ICMPV4_MAX_TRANSLATED_LIMIT;
        assert!(!limiter.admit(HOST, REMOTE, MonotonicMillis(u64::MAX), max, max));
        assert!(!limiter.admit(HOST, REMOTE, MonotonicMillis(u64::MAX / 2), 3, 1));
        assert!(limiter.is_pristine());
        // The largest reading that still fits is admitted; a later reading
        // that moved backward sees the bucket far in the future.
        let edge = u64::MAX / u64::from(max);
        assert!(limiter.admit(HOST, REMOTE, MonotonicMillis(edge), max, max));
        assert!(!limiter.is_pristine());
        assert!(!limiter.admit(HOST, REMOTE, MonotonicMillis(0), 1, 1));
        // An arrival time that cannot advance by one more error refuses.
        let bucket = limiter.bucket(HOST, REMOTE);
        limiter.arrival[bucket] = u64::MAX - 10;
        assert!(!limiter.admit(
            HOST,
            REMOTE,
            MonotonicMillis(u64::MAX / 1_000_000),
            1_000_000,
            1_000_000
        ));
    }
}
